"""Generate public/icons.js from the device's pixel icons (netcaliper.web.icons), so the dashboard
shares the boot-splash look. Run with the device venv: device/.venv/bin/python cloud/scripts/gen_icons.py"""

import json
import sys
from pathlib import Path

from netcaliper.web.icons import ICONS, icon, wordmark

out = Path(__file__).resolve().parents[1] / "public" / "icons.js"
icons = {name: str(icon(name)) for name in sorted(ICONS)}
text = (
    "// SPDX-License-Identifier: GPL-3.0-only\n"
    "// GENERATED by cloud/scripts/gen_icons.py from device/netcaliper/web/icons.py — do not edit.\n"
    f"export const ICONS = {json.dumps(icons, indent=1)};\n"
    f"export const WORDMARK = {json.dumps(str(wordmark()))};\n"
)
if "--check" in sys.argv:
    sys.exit(0 if out.exists() and out.read_text() == text else "public/icons.js is stale")
out.write_text(text)
